from functools import lru_cache
@lru_cache(maxsize=None)
def square(x):
    return x*x
print(square(3), square(3))

from functools import lru_cache
@lru_cache(maxsize=None)
def square(x: int) -> int:
    return x*x
print(square(3), square(3))

def empty(n):
    out = []
    return out
def a(n):
    if n <= 0:
        return empty(n)
    r = b(n - 1)
    r.append(n)
    return r
def b(n):
    return a(n)
print(a(3))

def empty(n):
    out = []
    return out
def a(n) -> list[int]:
    if n <= 0:
        return empty(n)
    r = b(n - 1)
    r.append(n)
    return r
def b(n):
    return a(n)
print(a(3))

from collections.abc import Mapping
from typing import Any
def describe(table: Mapping[str,Any]) -> list[str]:
 return [f'{k}={v}' for k,v in table.items()]
def count(*args: Any,**kwargs: Any) -> int:
 return len(args)+len(kwargs)
print(describe({'a':1}),describe({'x':'y'}),count(1,'a',k=2.0))

from typing import Any,Generator
def gen() -> Generator[int,Any,None]:
 x=yield 1
 print(x)
g=gen()
print(next(g))
try:
 g.send('hi')
except StopIteration:
 print('done')

