from collections import namedtuple
from typing import Any
Point=namedtuple('Point','x y')
def copy(p: Any) -> Any:
 return p._replace(x=p.x+1)
print(copy(Point(2,3)))

class Box:
 def __init__(self, value: object):
  self.value=value
print(Box(3).value, Box("ok").value)

from dataclasses import dataclass
from typing import Any
@dataclass
class Box:
 value: Any
print(Box(3).value)

from typing import Any
class Counter:
 def __init__(self):
  self.i=0
 def __iter__(self) -> Any:
  return self
 def __next__(self) -> Any:
  if self.i==3: raise StopIteration
  self.i+=1
  return self.i
print(list(Counter()),sum(Counter()))

