 def __setitem__(self,key: Any,value: Any) -> None:
  self.items[str(key)] = int(value)
 def __delitem__(self,key: object) -> None:
  del self.items[str(key)]
t=Table()
t[1]='12'
t['x']=3
print(t.items)
del t[1]
print(t.items)

